style:
.rdi-in{width:100%;box-sizing:border-box;font:inherit;font-size:16px;color:var(--ink);background:var(--paper);border:1px solid var(--line-strong);border-radius:2px;padding:12px 14px;transition:border-color 150ms ease,box-shadow 150ms ease}
.rdi-in:focus{outline:none;border-color:var(--artblue);box-shadow:0 0 0 3px rgba(50,19,183,0.15)}
.rdi-yn{position:relative;cursor:pointer}
.rdi-yn input{position:absolute;opacity:0;inset:0;margin:0;cursor:pointer}
.rdi-yn span{display:block;min-width:88px;text-align:center;padding:11px 20px;border:1px solid var(--line-strong);border-radius:2px;font-family:var(--font-display);font-weight:700;font-size:15px;transition:background 150ms ease,border-color 150ms ease,color 150ms ease}
.rdi-yn input:checked+span{background:var(--artblue);border-color:var(--artblue);color:#fff}
.rdi-yn input:focus-visible+span{box-shadow:0 0 0 3px rgba(50,19,183,0.15)}
.rdi-drop{display:block;border:1px dashed var(--artblue);background:var(--artlight);border-radius:2px;padding:28px;text-align:center;cursor:pointer;position:relative}
.rdi-drop input{position:absolute;inset:0;opacity:0;cursor:pointer}
@media (max-width:860px){.tir-hero{grid-template-columns:1fr !important}}
